FT result = FT(0);
auto first = polygon.begin();
auto second = first;
++second;
auto third = second;
++third;

while (third != polygon.end()) {
    result += traits.compute_area_2_object()(*first, *second, *third);
    second = third;
    ++third;
}
return result;

